//! The stage-4 real-machine smart-bone gate (parity plan › stage 4, ADR 0104):
//! bones-dial.moho was generated by Moho Pro 14.4 (Lua: gen_dial.lua) — a "SmartRig2"
//! bone layer with dial → swing → sub, the gradients canvas's 34 points classic-bound to
//! swing, and a smart-bone action "dial": inside the action swing's angle keys 0 → 0.6 →
//! 1.2 rad over frames 1/12/24, and on the mainline the dial bone keys −π/2 → +π/2
//! linearly over frames 0/24. Turning the dial scrubs the action: Moho's own FileRender
//! frames f0/f6/f12/f18/f24 are the truth, compared translation-aligned (4px-cell F1)
//! exactly like the other corpus gates.
//!
//! Negative control: strip every channel's actions — the rig returns to rest, and the
//! posed frames must then fail to match (the motion is action-borne, not mainline).
//! The corpus serialization this pins: the action rides on the POSED bone's channels
//! (pose.when/val = that channel's values during the action) while the dial bone carries
//! none — the action's NAME names the driving bone, whose base angle keys are the range
//! that scrubs the pose frames.

use anicraft_mohoproj_import::import_path;
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn corpus() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAOHOU_FIXTURES") {
        let p = PathBuf::from(dir);
        if p.is_dir() {
            return Some(p);
        }
    }
    let beside = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../maop-corpus/maop");
    beside.is_dir().then_some(beside)
}

fn content_mask(px: &[u8], w: u32, h: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let gw = w / step;
    let gh = h / step;
    let mut m = vec![false; (gw * gh) as usize];
    for gy in 0..gh {
        for gx in 0..gw {
            let mut on = 0u32;
            for dy in 0..step {
                for dx in 0..step {
                    let a = px[(((gy * step + dy) * w + gx * step + dx) * 4 + 3) as usize];
                    if a > 24 {
                        on += 1;
                    }
                }
            }
            m[(gy * gw + gx) as usize] = on > 0;
        }
    }
    (gw, gh, m)
}

fn best_shift(a: &[bool], b: &[bool], gw: u32, gh: u32, range: u32) -> (i64, i64, f64) {
    let (mut best_dx, mut best_dy) = (0i64, 0i64);
    let mut best_f1 = -1f64;
    let count = |dx: i64, dy: i64| -> f64 {
        let mut inter = 0u64;
        let mut na = 0u64;
        let mut nb = 0u64;
        for y in 0..gh as i64 {
            for x in 0..gw as i64 {
                let vb = b[(y as u32 * gw + x as u32) as usize];
                let ax = x - dx;
                let ay = y - dy;
                let va = ax >= 0 && ax < gw as i64 && ay >= 0 && ay < gh as i64 && a[(ay as u32 * gw + ax as u32) as usize];
                if va {
                    na += 1;
                }
                if vb {
                    nb += 1;
                }
                if va && vb {
                    inter += 1;
                }
            }
        }
        if na + nb == 0 {
            return 0.0;
        }
        2.0 * inter as f64 / (na + nb) as f64
    };
    for dy in -(range as i64)..=(range as i64) {
        for dx in -(range as i64)..=(range as i64) {
            let f1 = count(dx, dy);
            if f1 > best_f1 {
                best_f1 = f1;
                best_dx = dx;
                best_dy = dy;
            }
        }
    }
    (best_dx, best_dy, best_f1)
}

fn straight_rgba(ours: &anicraft_render::Pixmap) -> Vec<u8> {
    let mut rgba = Vec::with_capacity((ours.width * ours.height * 4) as usize);
    for p in &ours.data {
        let a = p[3];
        let un = |c: f32| if a > 0.0 { (c / a).clamp(0.0, 1.0) } else { 0.0 };
        rgba.extend_from_slice(&[(un(p[0]) * 255.0) as u8, (un(p[1]) * 255.0) as u8, (un(p[2]) * 255.0) as u8, (a * 255.0) as u8]);
    }
    rgba
}

fn render_mask(doc: &anicraft_doc::Document, frame: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let (w, h) = (doc.stage.width, doc.stage.height);
    let dl = anicraft_doc::evaluate(doc, frame);
    let view = anicraft_render::View { transform: anicraft_geom::Affine::IDENTITY, width: w, height: h, background: None };
    let ours = anicraft_render::render(&dl, &view).unwrap().0;
    let rgba = straight_rgba(&ours);
    content_mask(&rgba, w, h, step)
}

#[test]
fn imported_smart_bone_dial_matches_moho_frames() {
    let Some(dir) = corpus() else {
        eprintln!("skipped: no maop-corpus beside the workspace");
        return;
    };
    let path = dir.join("bones-dial.moho");
    if !path.is_file() {
        eprintln!("skipped: no bones-dial.moho in the corpus");
        return;
    }
    let (doc, _report) = import_path(&path).unwrap_or_else(|e| panic!("bones-dial.moho: {e}"));
    // The action came across: the swing bone's angle channel carries it (named after the
    // dial), with the pose 0/0.6/1.2 at frames 0/12/24 (y-flipped to screen radians).
    let rig = doc.timeline(0).layers.iter().find(|l| l.kind == anicraft_doc::LayerKind::Bone).unwrap();
    let sk = rig.skeleton.as_ref().unwrap();
    assert_eq!(sk.bones.iter().map(|b| b.name.as_str()).collect::<Vec<_>>(), ["dial", "swing", "sub"]);
    // The dial carries the LOOKUP (its own angle channel, pose = dial angles per action
    // frame); the swing carries its own pose. Both y-flipped to screen radians.
    let dial = &sk.bones[0];
    assert_eq!(dial.angle.actions.len(), 1, "the lookup rides on the dial");
    let lookup = &dial.angle.actions[0];
    assert_eq!(lookup.name, "dial");
    assert!((lookup.pose.keys.last().unwrap().val + std::f32::consts::FRAC_PI_2).abs() < 1e-3, "the lookup ends at the dial's +π/2 (screen −π/2): {:?}", lookup.pose.keys.last().unwrap().val);
    let swing = &sk.bones[1];
    assert_eq!(swing.angle.actions.len(), 1, "the action rides on the posed bone");
    let a = &swing.angle.actions[0];
    assert_eq!(a.name, "dial");
    let frames: Vec<u32> = a.pose.keys.iter().map(|k| k.frame).collect();
    assert_eq!(frames, [0, 1, 12, 24], "the base key at 0 and the action keys at 1/12/24");
    assert!((a.pose.keys[2].val + 0.6).abs() < 1e-3, "{:?}", a.pose.keys[2].val);

    let (w, h) = (doc.stage.width, doc.stage.height);
    let step = 4u32;
    for (name, frame) in [("f0", 0u32), ("f6", 6), ("f12", 12), ("f18", 18), ("f24", 24)] {
        let Ok(moho_png) = std::fs::read(dir.join(format!("inputs/bones-dial-{name}.png"))) else {
            eprintln!("skipped {name}: no Moho render");
            continue;
        };
        let moho = anicraft_doc::decode_png(&moho_png).unwrap();
        assert_eq!((moho.width, moho.height), (w, h));
        let (gw, gh, m_mask) = content_mask(&moho.rgba, w, h, step);
        let (gw2, gh2, o_mask) = render_mask(&doc, frame, step);
        assert_eq!((gw, gh), (gw2, gh2));
        let (dx, dy, f1) = best_shift(&o_mask, &m_mask, gw, gh, 75);
        println!("bones-dial {name}: best shift ({dx}, {dy}) cells = ({}px, {}px), aligned F1 {f1:.3}", dx * step as i64, dy * step as i64);

        // The negative control on the posed frames: strip the actions — the rig sits at
        // rest while Moho's frame follows the dial.
        if frame > 0 {
            let mut flat = doc.clone();
            for l in flat.timeline_mut(0).layers.iter_mut() {
                let l = Arc::make_mut(l);
                if let Some(s) = l.skeleton.as_mut() {
                    let s = Arc::make_mut(s);
                    for b in &mut s.bones {
                        b.angle.actions.clear();
                        b.pos.actions.clear();
                        b.scale.actions.clear();
                    }
                }
            }
            let (_, _, u_mask) = render_mask(&flat, frame, step);
            let (_, _, uf1) = best_shift(&u_mask, &m_mask, gw, gh, 75);
            println!("bones-dial {name}: NO-ACTION control F1 {uf1:.3}");
            let why = format!("bones-dial {name}: action F1 {f1:.3} must beat the rest-pose control {uf1:.3} — the dial does not drive the rig");
            assert!(f1 > uf1 + 0.03, "{why}");
        }
        let why = format!("bones-dial {name}: aligned overlap F1 {f1:.3} — the imported dial does not reproduce Moho's frame");
        assert!(f1 > 0.18, "{why}");
    }
}
